export function RetryState({
  message = "{{message}}",
  retryLabel = "{{retryLabel}}",
  attempt = {{attempt}},
  isRetrying = {{isRetrying}},
}) {
  return (
    <div role="alert" style={{ display: "flex", alignItems: "center", gap: 12, maxWidth: 380, padding: "12px 16px",
      boxSizing: "border-box", borderRadius: 10, background: "color-mix(in srgb, #B3261E 8%, #FAF7F2)",
      border: "1px solid #B3261E", font: "13.5px/1.4 system-ui, sans-serif", color: "#241430" }}>
      <span aria-hidden="true" style={{ width: 22, height: 22, borderRadius: "50%", background: "#B3261E", color: "#FAF7F2",
        flexShrink: 0, display: "grid", placeItems: "center", fontSize: 12, fontWeight: 700 }}>!</span>
      <div style={{ flex: 1 }}>
        <p style={{ margin: 0, fontWeight: 700 }}>{message}</p>
        <p style={{ margin: "2px 0 0", color: "#241430b3", fontSize: 12 }}>Attempt {attempt}</p>
      </div>
      <button type="button" style={{ display: "inline-flex", alignItems: "center", gap: 6, border: "none", borderRadius: 8,
        background: "#241430", color: "#FAF7F2", fontWeight: 600, fontSize: 12.5, padding: "8px 14px",
        cursor: isRetrying ? "progress" : "pointer", opacity: isRetrying ? 0.75 : 1, whiteSpace: "nowrap" }}>
        {isRetrying && <span aria-hidden="true" className="retry-spinner" style={{ width: 12, height: 12, borderRadius: "50%", border: "2px solid #FAF7F244",
          borderTopColor: "#FAF7F2" }} />}
        {retryLabel}
      </button>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .retry-spinner { animation: retry-react-spin .7s linear infinite; }
          @keyframes retry-react-spin { to { transform: rotate(360deg); } }
        }
      `}</style>
    </div>
  );
}
